package com.technova.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,Object>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));} @ExceptionHandler(Exception.class) ResponseEntity<Map<String,Object>> generic(Exception e){return ResponseEntity.status(500).body(Map.of("error","Error interno","detalle",e.getMessage()==null?"":e.getMessage()));} }
